callGraph.callee:
getCurrentUser()
      .then((data) => {
        if (cancelled) {
          return;
        }

        setLoggedInUser(data.user);

        localStorage.setItem(
          "loggedInUser",
          JSON.stringify(data.user)
        );
      })
      .catch(() => {
        if (cancelled) {
          return;
        }

        //no valid session cookie: forget the cached user so the
        //login page is shown
        localStorage.removeItem("loggedInUser");
        setLoggedInUser(null);
      })
      .finally

getCurrentUser()
      .then((data) => {
        if (cancelled) {
          return;
        }

        setLoggedInUser(data.user);

        localStorage.setItem(
          "loggedInUser",
          JSON.stringify(data.user)
        );
      })
      .catch

loadYouTubeApi()
            .then((YT) => {
                if (
                    disposed ||
                    !containerRef.current ||
                    !YT?.Player
                ) {
                    return;
                }

                player = new YT.Player(
                    containerRef.current,
                    {
                        videoId:
                            video.videoId,

                        playerVars: {
                            autoplay: 1,
                            rel: 0
                        },

                        events: {
                            onReady:
                                (event) => {
                                    const iframe =
                                        event
                                            ?.target
                                            ?.getIframe?.();

                                    if (iframe) {
                                        iframe.style.width =
                                            "100%";

                                        iframe.style.height =
                                            "100%";
                                    }
                                },

                            onStateChange:
                                () => {
                                    if (
                                        !player
                                    ) {
                                        return;
                                    }

                                    const state =
                                        player.getPlayerState
                                            ? player.getPlayerState()
                                            : -1;

                                    const time =
                                        player.getCurrentTime
                                            ? player.getCurrentTime()
                                            : 0;

                                    if (
                                        state ===
                                        YT.PlayerState
                                            .PLAYING &&
                                        time >
                                        lastPosition
                                    ) {
                                        watchedSeconds +=
                                            time -
                                            lastPosition;
                                    }

                                    lastPosition =
                                        time;

                                    //send as soon as playback ends
                                    if (
                                        state ===
                                        YT.PlayerState
                                            .ENDED
                                    ) {
                                        reportWatchTime();
                                    }
                                }
                        }
                    }
                );
            })
            .catch
